import React, { useState, useMemo, useCallback } from "react";
import { Box, Typography, Button, Paper, TextField, IconButton, CircularProgress, Alert } from "@mui/material";
import { Delete as DeleteIcon, CloudUpload as UploadIcon } from "@mui/icons-material";
import "./Converter.css";

// parseCoord same as before
function parseCoord(coordStr) {
  if (!coordStr) return null;
  const match = coordStr.trim().match(/^([NSEW])(\d+)\.(\d+)\.(\d+(?:\.\d+)?)$/);
  if (!match) return null;
  const [, dir, degStr, minStr, secStr] = match;
  const deg = parseInt(degStr, 10);
  const min = parseInt(minStr, 10);
  const sec = parseFloat(secStr);
  let val = deg + min / 60 + sec / 3600;
  if (dir === "S" || dir === "W") val = -val;
  return val;
}

// parseTopSky same as before
function parseTopSky(text) {
  const lines = text.split("\n");
  const features = [];
  let current = null;

  lines.forEach((lineRaw) => {
    const line = lineRaw.trim();
    if (!line || line.startsWith(";") || line.startsWith("//")) return;

    if (line.startsWith("AREA:T:")) {
      if (current && current.coords.length > 2) features.push(current);
      const name = line.split(":")[2];
      current = { name, type: null, lowerFL: null, upperFL: null, coords: [] };
    } else if (line.startsWith("CATEGORY:") && current) {
      current.type = line.split(":")[1].trim();
    } else if (line.startsWith("LIMITS:") && current) {
      const parts = line.split(":");
      current.lowerFL = parseInt(parts[1], 10);
      current.upperFL = parseInt(parts[2], 10);
    } else if ((line.startsWith("N") || line.startsWith("S")) && current) {
      const parts = line.split(/\s+/).filter(Boolean);
      if (parts.length >= 2) {
        const lat = parseCoord(parts[0]);
        const lon = parseCoord(parts[1]);
        if (lat !== null && lon !== null) {
          current.coords.push([lon, lat]);
        }
      }
    }
  });

  if (current && current.coords.length > 2) features.push(current);

  return {
    type: "FeatureCollection",
    features: features.map((f) => ({
      type: "Feature",
      properties: {
        name: f.name,
        type: f.type,
        lowerFL: f.lowerFL,
        upperFL: f.upperFL,
        mustBeBookedWith: [],
        foreignClusters: [],
      },
      geometry: { type: "Polygon", coordinates: [[...f.coords, f.coords[0]]] },
    })),
  };
}

// Memoized Row Component
const AirspaceRow = React.memo(({ row, onUpdate, onDelete, error }) => {
  const handleChange = (field, value) => onUpdate(row.properties.name, field, value);

  return (
    <tr>
      <td>{row.properties.name}</td>
      <td>{row.properties.type}</td>
      <td>{row.properties.lowerFL}</td>
      <td>{row.properties.upperFL}</td>
      <td>
        <TextField
            size="small"
            defaultValue={row.properties.mustBeBookedWith.join(", ")}
            placeholder="TSA1, TSA2"
            onBlur={(e) => handleChange("mustBeBookedWith", e.target.value)}
        />
        </td>
        <td>
        <TextField
            size="small"
            error={error}
            defaultValue={row.properties.foreignClusters.join(", ")}
            placeholder="efin, eett"
            onBlur={(e) => handleChange("foreignClusters", e.target.value)}
        />
      </td>
      <td>
        <IconButton onClick={() => onDelete(row.properties.name)}>
          <DeleteIcon />
        </IconButton>
      </td>
    </tr>
  );
});

const Converter = () => {
  const [geojson, setGeojson] = useState(null);
  const [fileName, setFileName] = useState(null);
  const [loading, setLoading] = useState(false);
  const [selectedTypes, setSelectedTypes] = useState(new Set());
  const [errors, setErrors] = useState({});

  document.title = "V-LARA Converter";

  const handleFile = (file) => {
    setLoading(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      setTimeout(() => {
        const gj = parseTopSky(e.target.result);
        setGeojson(gj);
        setFileName(file.name);
        // initially all types selected
        setSelectedTypes(new Set(gj.features.map((f) => f.properties.type)));
        setLoading(false);
      }, 100);
    };
    reader.readAsText(file);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    if (e.dataTransfer.files.length) handleFile(e.dataTransfer.files[0]);
  };

  const toggleType = useCallback((type) => {
    setSelectedTypes((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(type)) newSet.delete(type);
      else newSet.add(type);
      return newSet;
    });
  }, []);

  const handleDelete = useCallback((name) => {
    setGeojson((prev) => ({
      ...prev,
      features: prev.features.filter((f) => f.properties.name !== name),
    }));
  }, []);

  const handleUpdate = useCallback((name, field, value) => {
    setGeojson((prev) => ({
      ...prev,
      features: prev.features.map((f) => {
        if (f.properties.name !== name) return f;
        let arr = value
          .split(",")
          .map((s) => s.trim())
          .filter((s) => s.length > 0);

        let err = false;
        if (field === "foreignClusters") {
          arr = arr.map((s) => s.toLowerCase());
          if (arr.some((s) => s.length !== 4)) err = true;
        }

        setErrors((prevErrs) => ({ ...prevErrs, [name]: err }));
        return { ...f, properties: { ...f.properties, [field]: arr } };
      }),
    }));
  }, []);

  const filteredFeatures = useMemo(
    () =>
      geojson
        ? geojson.features.filter((f) => selectedTypes.has(f.properties.type))
        : [],
    [geojson, selectedTypes]
  );

  const handleDownload = () => {
    if (!geojson) return;
    // Manually construct compact GeoJSON
    const compactFeatures = geojson.features.map((f) => ({
      type: "Feature",
      properties: {
        name: f.properties.name,
        type: f.properties.type,
        lowerFL: f.properties.lowerFL,
        upperFL: f.properties.upperFL,
        mustBeBookedWith: f.properties.mustBeBookedWith,
        foreignClusters: f.properties.foreignClusters,
      },
      geometry: {
        type: "Polygon",
        coordinates: [f.geometry.coordinates[0].map(coord => [coord[0], coord[1]])], // 1 line coords
      },
    }));
  
    const compactGeoJSON = JSON.stringify(
      { type: "FeatureCollection", features: compactFeatures }
    );
  
    const blob = new Blob([compactGeoJSON], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download =  "xxxx.geojson";
    a.click();
  };  

  const types = useMemo(
    () => (geojson ? [...new Set(geojson.features.map((f) => f.properties.type))] : []),
    [geojson]
  );

  return (
    <Box className="converter-root">
      {!geojson && !loading && (
        <Typography variant="h6" sx={{mb: 2, textAlign: 'center'}}>Convert TopSky Areas to LARA GeoJSON format</Typography>

      )}
      {!geojson && !loading && (
        <Paper
          className="upload-box"
          elevation={0}
          onDrop={handleDrop}
          onDragOver={(e) => e.preventDefault()}
          onClick={() => document.getElementById("fileInput").click()}
        >
          <UploadIcon sx={{ fontSize: 80, color: "#666" }} />
          <Typography variant="body1" color="textSecondary">
            {fileName || "TopSkyAreas.txt"}
          </Typography>
          <input
            id="fileInput"
            type="file"
            accept=".txt"
            style={{ display: "none" }}
            onChange={(e) => {
              if (e.target.files.length) handleFile(e.target.files[0]);
            }}
          />
        </Paper>
      )}

      {loading && (
        <Box sx={{ textAlign: "center", mt: 10 }}>
          <CircularProgress />
          <Typography sx={{ mt: 2 }}>Loading airspaces</Typography>
          <Alert severity="warning" sx={{mt: 2, maxWidth: '400px', mx: "auto" }}>
            Large files with many airspaces may take a little longer to load.
          </Alert>
        </Box>
      )}

      {geojson && !loading && (
        <Box className="editor-section">
          <Typography variant="h5" sx={{mb: 2}}>
            TopSky Airspaces
          </Typography>

          <Alert severity="info" sx={{mb: 2}}>
            Verify GeoJSON data in{" "}
            <span
                onClick={() => {
                window.open(`${window.location.origin}/#/dqt`, "_blank", "noopener,noreferrer");
                }}
                style={{ color: "#1976d2", textDecoration: "underline", cursor: "pointer" }}
            >
                Data Quality Tool
            </span>{" "}
            after converting. Only reservable areas shall be uploaded to V-LARA.
          </Alert>

          <Alert severity="warning" sx={{mb: 2}}>
            Large files with many airspaces may take a little longer to update. Please be patient while changes are applied.
          </Alert>

          <p style={{fontWeight: 'bold'}}>Filter Airspace Types</p>

          <Box sx={{ mb: 2 }}>
            {types.map((t) => (
              <Button
                key={t}
                variant={selectedTypes.has(t) ? "contained" : "outlined"}
                color="success"
                sx={{ mr: 1, mb: 1, borderRadius: 0 }}
                onClick={() => toggleType(t)}
              >
                {t}
              </Button>
            ))}

          </Box>

          <Box sx={{ overflowX: "auto" }}>
             <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                <tr>
                    <th>Name</th>
                    <th>Type</th>
                    <th>Lower FL</th>
                    <th>Upper FL</th>
                    <th>mustBeBookedWith</th>
                    <th>foreignClusters</th>
                    <th>Delete</th>
                </tr>
                </thead>
                <tbody>
                {filteredFeatures.map((row) => (
                    <AirspaceRow
                    key={row.properties.name}
                    row={row}
                    onUpdate={handleUpdate}
                    onDelete={handleDelete}
                    error={errors[row.properties.name] || false}
                    />
                ))}
                </tbody>
            </table>
          </Box>

          <Box sx={{ display: "flex", justifyContent: "center", mt: 4, mb: 2 }}>
            <Button
                variant="contained"
                color="primary"
                sx={{ borderRadius: 0 }}
                onClick={handleDownload}
            >
                Download GeoJSON
            </Button>
          </Box>
        </Box>
        )}
    </Box>
);};

export default Converter;
